import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { defineConfig } from "astro/config";
import sitemap from "@astrojs/sitemap";
import icon from "astro-icon";
import tailwindcss from "@tailwindcss/vite";

const SITE = "https://__DOMAIN__";

// lastmod dates from git history, pre-generated by scripts/generate-sitemap-dates.js
// and committed so shallow-clone CI builds get accurate dates.
// From the cwd, not import.meta.url: once bundled, a module's URL depends on
// the chunk it lands in, and a wrong path breaks file reads.
const sitemapDates: Record<string, string> = JSON.parse(
  readFileSync(resolve(process.cwd(), "generated/sitemap-dates.json"), "utf-8")
);

const ROUTE_META: Record<string, { changefreq: string; priority: number }> = {
  "/": { changefreq: "weekly", priority: 1.0 },
  "/about": { changefreq: "monthly", priority: 0.5 },
  "/tos": { changefreq: "yearly", priority: 0.3 },
  "/privacy-policy": { changefreq: "yearly", priority: 0.3 },
};

export default defineConfig({
  site: SITE,
  trailingSlash: "never",
  // 'file' emits about.html (not about/index.html) so Cloudflare serves /about
  // without a trailing-slash redirect — exact parity with the old Next export.
  build: { format: "file" },
  // Astro 7's default ('jsx') drops the whitespace between inline elements and
  // across line breaks, which glues words together in rendered text.
  compressHTML: true,
  integrations: [
    icon({ include: { lucide: ["*"] } }),
    sitemap({
      serialize(item) {
        const path = new URL(item.url).pathname.replace(/\/$/, "") || "/";
        const meta = ROUTE_META[path] ?? { changefreq: "monthly", priority: 0.5 };
        return {
          ...item,
          // Root canonical is https://__DOMAIN__ without trailing slash (live parity).
          url: path === "/" ? SITE : `${SITE}${path}`,
          lastmod: sitemapDates[path] ?? new Date().toISOString(),
          changefreq: meta.changefreq as never,
          priority: meta.priority,
        };
      },
    }),
    // Since @astrojs/sitemap 3.7.4 the homepage is written as https://__DOMAIN__/.
    // Keep the bare origin so the sitemap matches the homepage canonical.
    {
      name: "sitemap-root-loc",
      hooks: {
        "astro:build:done": ({ dir }) => {
          // The homepage can land in any child sitemap once the site outgrows one file.
          for (const name of readdirSync(dir)) {
            if (!/^sitemap-\d+\.xml$/.test(name)) continue;
            const file = new URL(name, dir);
            const xml = readFileSync(file, "utf-8");
            writeFileSync(file, xml.replaceAll(`<loc>${SITE}/</loc>`, `<loc>${SITE}</loc>`));
          }
        },
      },
    },
  ],
  vite: {
    // Cast: @tailwindcss/vite ships its own vite types that clash with astro's nested vite.
    plugins: [tailwindcss() as never],
    build: {
      // Vite 8 minifies CSS with Lightning CSS by default, which drops
      // -webkit-backdrop-filter (needed by Safari < 18). esbuild is a direct
      // dependency: Astro 7.4 no longer brings it.
      cssMinify: "esbuild",
      // Vite 6's targets. Without them breakpoints come out as `width>=`,
      // ignored before Safari 16.4.
      cssTarget: ["safari14", "chrome90", "firefox90", "edge90"],
    },
  },
});
